import sys, os, time, json
sys.argv = ["bench", "--node-id", "A", "--port", "9001"]

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
os.chdir(os.path.join(SCRIPT_DIR, "_run", "run_A"))
sys.path.insert(0, os.getcwd())

from backend.crypto.layered_encryption import layered_encryption
from backend.crypto.key_manager import key_manager

# Load D's real public key (as generated by the actual prototype)
d_pub_path = os.path.join(SCRIPT_DIR, "_run", "run_D", "backend", "keys", "D_public.key")
d_pub = open(d_pub_path, "rb").read().hex()

MESSAGE = "Benchmark message payload for Curve25519 authenticated encryption timing."
N = 500

# Warm-up (exclude first-call JIT/import overhead)
for _ in range(10):
    layered_encryption.encrypt_for_hop(d_pub, MESSAGE)

times = []
sample_ciphertext = None
for i in range(N):
    t0 = time.perf_counter()
    ct = layered_encryption.encrypt_for_hop(d_pub, MESSAGE)
    t1 = time.perf_counter()
    times.append((t1 - t0) * 1000.0)  # ms
    if i == 0:
        sample_ciphertext = ct

out_path = os.path.join(SCRIPT_DIR, "enc_times.json")
with open(out_path, "w") as f:
    json.dump({"times_ms": times, "sample_ciphertext": sample_ciphertext,
               "sender_public_key": key_manager.get_public_key(),
               "message": MESSAGE}, f)

print("ENC_DONE", len(times), "->", out_path)
